// Parse the Next.js embedded JSON payload — the page ships every article's
// full body, title, pillar, and metadata inside self.__next_f.push([1,"..."])
// chunks. Scan character-by-character (regex backtracks on multi-MB chunks).

const html = items[0].json.data || items[0].json.body || items[0].json.body_html || '';
if (!html || typeof html !== 'string') {
  throw new Error('Fetch did not return HTML. Got keys: ' + Object.keys(items[0].json || {}).join(', '));
}

function extractPushChunks(source) {
  const chunks = [];
  const marker = 'self.__next_f.push([1,"';
  let i = 0;
  while (i < source.length) {
    const start = source.indexOf(marker, i);
    if (start < 0) break;
    let j = start + marker.length;
    while (j < source.length) {
      const c = source.charCodeAt(j);
      if (c === 92) { j += 2; continue; }
      if (c === 34) break;
      j++;
    }
    if (j < source.length) {
      chunks.push(source.slice(start + marker.length, j));
      i = j + 1;
    } else break;
  }
  return chunks;
}

function unescapeJsString(s) {
  try { return JSON.parse('"' + s + '"'); } catch (e) { return null; }
}

const chunks = extractPushChunks(html);
if (chunks.length === 0) {
  throw new Error('Zero push chunks found. HTML length: ' + html.length);
}

let piecesArray = null;
const bodyById = {};

for (const chunk of chunks) {
  const decoded = unescapeJsString(chunk);
  if (decoded === null) continue;

      const bodyRe = /(?:^|\n)([0-9a-f]+):T[0-9a-f]+,([\s\S]*?)(?=(?:\n[0-9a-f]+:)|$)/g;
      let bm; let matchedBody = false;
      while ((bm = bodyRe.exec(decoded)) !== null) { bodyById[bm[1]] = bm[2]; matchedBody = true; }    if (matchedBody) continue;

  if (!decoded.includes('"pieces"')) continue;
  const jsonStart = decoded.search(/[{\[]/);
  if (jsonStart < 0) continue;

  let payload;
  try { payload = JSON.parse(decoded.slice(jsonStart)); }
  catch (e) { continue; }

  const stack = [payload];
  while (stack.length) {
    const node = stack.pop();
    if (!node || typeof node !== 'object') continue;
    if (Array.isArray(node.pieces)) { piecesArray = node.pieces; break; }
    if (Array.isArray(node)) { for (const el of node) stack.push(el); }
    else { for (const v of Object.values(node)) stack.push(v); }
  }
  if (piecesArray) break;
}

if (!piecesArray) {
  throw new Error('Scanned ' + chunks.length + ' chunks but none contained a pieces[] array.');
}

function resolveBody(bm) {
  if (typeof bm !== 'string') return '';
  const ref = bm.match(/^\$([0-9a-f]+)$/);
  if (ref && bodyById[ref[1]]) return bodyById[ref[1]];
  return bm;
}

// Dedupe by normalized title (the blog republishes near-identical essays
// under new slugs), keep the most recent version of each.
const byTitle = new Map();
for (const p of piecesArray) {
  if (!p || !p.slug || !p.title) continue;
  const key = p.title.toLowerCase().replace(/\s+/g, ' ').trim();
  const existing = byTitle.get(key);
  const pubDate = new Date(p.published_at || p.created_at || 0);
  if (!existing || pubDate > new Date(existing.published_at || existing.created_at || 0)) {
    byTitle.set(key, p);
  }
}

// Filter out slugs already in the processed log.
const logItems = $items('Read Processed Log') || [];
const processedSlugs = new Set(
  logItems.map(r => (r.json.slug || '').toString().trim()).filter(Boolean)
);

const out = [];
for (const p of byTitle.values()) {
      const isNew = !processedSlugs.has(p.slug);
  out.push({
    json: {
      slug: p.slug,
              is_new: isNew,
      title: p.title,
      subtitle: p.subtitle || '',
      url: `https://app.gofunditnow.dev/thinking/${p.slug}`,
      pillar_title: p.pillar_title || '',
            body_markdown: (() => { const b = resolveBody(p.body_markdown); return (typeof b === 'string' && /^\$[0-9a-f]+$/.test(b.trim())) ? (p.subtitle || p.title || '') : b; })(),

      published_at: p.published_at || p.created_at || ''
    }
  });
}

return out;

// Grab the og:image meta tag if present. Skip if absent — no fallback.
const html = items[0].json.data || items[0].json.body || '';
const article = $node['Loop Over Articles'].json;

let ogImage = '';
if (typeof html === 'string' && html) {
  const m = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i)
         || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
  if (m) ogImage = m[1];
}

return [{ json: { ...article, og_image: ogImage } }];

