    scheduledTime: (i === 0 ? firstPost : secondPost).toISO()
  }
}));

// Select up to 2 articles to post this run.
// Priority: newest un-posted articles first; if none are new, recycle from the existing pool (least-recently-posted).
const MAX = 2;

const items = $input.all();

// Build a map of slug -> most recent posted timestamp from the processed log.
let logRows = [];
try { logRows = $('Read Processed Log').all(); } catch (e) { logRows = []; }
const lastPosted = {};
for (const r of logRows) {
    const j = r.json || {};
    const slug = String(j.slug || '').trim();
    if (!slug) continue;
    const ts = Date.parse(j.posted_at || j.date || j.scheduledTime || j.updated_at || '') || 0;
    if (!(slug in lastPosted) || ts > lastPosted[slug]) lastPosted[slug] = ts;
}

const toTime = (v) => Date.parse(v) || 0;

const newItems = items.filter(i => i.json && i.json.is_new === true);
const poolItems = items.filter(i => i.json && i.json.is_new !== true);

let selected;
if (newItems.length > 0) {
    selected = newItems
      .sort((a, b) => toTime(b.json.published_at) - toTime(a.json.published_at))
      .slice(0, MAX);
} else {
    selected = poolItems
      .sort((a, b) => (lastPosted[a.json.slug] || 0) - (lastPosted[b.json.slug] || 0))
      .slice(0, MAX);
}

return selected;

const items = $input.all();
