  let dt = DateTime.now().setZone(zone).set({ weekday: weekday, hour: 9, minute: 0, second: 0, millisecond: 0 }).plus({ hours: slot * 3 });
  if (dt < DateTime.now()) dt = dt.plus({ weeks: 1 });
  return { json: Object.assign({}, item.json, { scheduledTime: dt.toISO() }) };
});
